CREATE TABLE feature_flags(id BINARY(16) PRIMARY KEY,flag_key VARCHAR(255) NOT NULL UNIQUE,description VARCHAR(1000) NOT NULL,enabled BOOLEAN NOT NULL,kill_switch BOOLEAN NOT NULL,rollout_percentage INT NOT NULL,client_targets_json TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,revision BIGINT NOT NULL);
CREATE TABLE feature_flag_overrides(id BINARY(16) PRIMARY KEY,flag_id BINARY(16) NOT NULL,scope_type VARCHAR(30) NOT NULL,scope_id BINARY(16) NOT NULL,enabled BOOLEAN NOT NULL,rollout_percentage INT NOT NULL,UNIQUE(flag_id,scope_type,scope_id),FOREIGN KEY(flag_id) REFERENCES feature_flags(id) ON DELETE CASCADE);
CREATE TABLE feature_flag_history(id BINARY(16) PRIMARY KEY,flag_id BINARY(16) NOT NULL,actor_id BINARY(16) NOT NULL,action VARCHAR(100) NOT NULL,before_json TEXT,after_json TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL,INDEX idx_flag_history(flag_id,created_at),FOREIGN KEY(flag_id) REFERENCES feature_flags(id) ON DELETE CASCADE);